#!/usr/bin/env python3
"""Validate current canonical human domain tables without aggregate copies."""

from __future__ import annotations

import json
import re
from pathlib import Path

from domain_tables import DOMAIN_TABLES, D7_TABLE, D8_TABLE, D9_TABLE, read_domain_table

ROOT = Path(__file__).resolve().parents[1]
FOUNDATION = ROOT / "knowledge/d1-d9-foundation.json"
D7_AUTHORITY = ROOT / "knowledge/d7-ratified.json"
D8_AUTHORITY = ROOT / "knowledge/d8-ratified.json"
D9_AUTHORITY = ROOT / "knowledge/d9-ratified.json"


def fail(message: str) -> None:
    raise SystemExit(f"DOMAIN-TABLES: FAIL: {message}")


def en_matches_resident(value: str, resident: str) -> bool:
    candidate = value.casefold()
    target = resident.casefold()
    if candidate == target:
        return True
    if candidate.endswith(("?", "!")) and candidate[:-1] == target:
        return True
    return False


def validate_dense_table(path: Path, width: int, residents: dict[str, str], require_human: bool):
    rows = read_domain_table(path)
    domain = f"D{width}"
    expected_count = 1 << width
    if len(rows) != expected_count:
        fail(f"{domain}: expected {expected_count} rows, found {len(rows)}")

    expected_bits = [f"{n:0{width}b}" for n in range(expected_count)]
    actual_bits = [row.bits for row in rows]
    if actual_bits != expected_bits:
        fail(f"{domain}: rows must be ordered exact-width 0..{expected_count - 1}")

    for row in rows:
        resident = residents.get(row.bits)
        if resident is None:
            fail(f"{domain}:{row.bits}: absent from ratified authority")

        if domain == "D3" and row.bits == "000":
            # Every projection of the structural EMPTY value is literally ().
            surfaces = ("uk", "ukr", "san", "en", "lisp", "sym")
            if any(getattr(row, name) != "()" for name in surfaces):
                fail("D3:000: all six columns must be literal ()")
            continue

        if row.en is None:
            fail(f"{domain}:{row.bits}: missing en")
        if not en_matches_resident(row.en, resident):
            fail(f"{domain}:{row.bits}: en {row.en!r} does not match resident {resident!r}")

        if width in {8, 9}:
            if row.lisp != resident:
                fail(f"D{width}:{row.bits}: LISP {row.lisp!r} must preserve ratified resident {resident!r}")
        elif require_human and row.lisp is None and domain not in {"D2"}:
            fail(f"{domain}:{row.bits}: missing LISP")

        if require_human:
            for attr in ("uk", "ukr", "san"):
                if getattr(row, attr) is None:
                    fail(f"{domain}:{row.bits}: missing {attr}")

        predicate = row.en.endswith("?")
        if predicate:
            if row.uk is not None and not row.uk.endswith("?"):
                fail(f"{domain}:{row.bits}: predicate uk must end in ?")
            if row.ukr is not None and not row.ukr.endswith("?"):
                fail(f"{domain}:{row.bits}: predicate ukr must end in ?")
            if row.san is not None and row.san.endswith("?"):
                fail(f"{domain}:{row.bits}: predicate san must not end in ?")

    return rows


def validate_d7(authority: dict):
    if authority.get("status") != "owner-ratified" or authority.get("authority") != "#3572":
        fail("D7 authority is not owner-ratified #3572")

    rows = read_domain_table(D7_TABLE)
    residents = authority["residents"]
    if len(rows) != 126:
        fail(f"D7: expected 126 rows, found {len(rows)}")

    reserved = set(authority["reserved_coordinates"])
    actual_bits = [row.bits for row in rows]
    expected_bits = sorted(residents, key=lambda bits: int(bits, 2))

    if actual_bits != expected_bits:
        fail("D7: rows must match ratified resident coordinates exactly")
    if any(bits in reserved for bits in actual_bits):
        fail("D7: owner-reserved pinned coordinate appeared as a semantic row")

    for row in rows:
        if row.lisp is not None:
            fail(f"D7:{row.bits}: LISP must stay () because D7 is sound/text, not a Lisp operator")
    return rows


def validate_compact_uk(rows) -> None:
    for row in rows:
        if row.domain == "D7":
            continue  # D7 cells are glyphs, not verbose/compact human names.
        if row.uk is None or row.ukr is None:
            fail(f"{row.domain}:{row.bits}: uk/ukr must both be present")

        if len(row.uk) > len(row.ukr):
            fail(
                f"{row.domain}:{row.bits}: compact uk surface {row.uk!r} "
                f"is longer than expanded ukr {row.ukr!r}"
            )

        if "-на-місці" in row.uk:
            fail(f"{row.domain}:{row.bits}: compact uk must use ! instead of -на-місці")

        if row.domain == "D7" and (row.uk.startswith("звук-") or row.uk.startswith("текст-")):
            fail(f"{row.domain}:{row.bits}: compact uk must omit redundant D7 context prefix")

        if row.domain == "D7" and row.uk.startswith("український-"):
            fail(f"{row.domain}:{row.bits}: compact uk should use the stable укр- prefix")

        mutation = (
            row.uk.endswith("!")
            or row.ukr.endswith("!")
            or (row.en is not None and row.en.endswith("!"))
            or "на-місці" in row.ukr
        )
        if mutation:
            if not row.uk.endswith("!"):
                fail(f"{row.domain}:{row.bits}: destructive uk surface must end in !")
            if not row.ukr.endswith("!"):
                fail(f"{row.domain}:{row.bits}: destructive ukr surface must end in !")
            if row.en is None or not row.en.endswith("!"):
                fail(f"{row.domain}:{row.bits}: destructive en surface must end in !")

        if row.lisp and re.fullmatch(r"C[AD]{2,7}R", row.lisp.upper()):
            path = row.lisp.upper()[1:-1]
            expected = "-".join("п" if ch == "A" else "р" for ch in path)
            if row.uk != expected:
                fail(
                    f"{row.domain}:{row.bits}: selector uk {row.uk!r} "
                    f"must be compact path {expected!r}"
                )

    by_lisp = {row.lisp: row for row in rows if row.lisp}
    for name, expected in (("GCD", "нсд"), ("LCM", "нск")):
        row = by_lisp.get(name)
        if row is not None and row.uk != expected:
            fail(f"{row.domain}:{row.bits}: {name} compact uk must be {expected!r}")


def main() -> int:
    foundation = json.loads(FOUNDATION.read_text(encoding="utf-8"))
    total = 0
    all_rows = []

    for width, path in enumerate(DOMAIN_TABLES, start=1):
        residents = foundation["domains"][f"D{width}"]["residents"]
        rows = validate_dense_table(path, width, residents, require_human=True)
        all_rows.extend(rows)
        total += 1 << width

    d7_authority = json.loads(D7_AUTHORITY.read_text(encoding="utf-8"))
    d7_rows = validate_d7(d7_authority)
    all_rows.extend(d7_rows)
    total += 126

    d8_authority = json.loads(D8_AUTHORITY.read_text(encoding="utf-8"))
    if d8_authority.get("status") != "owner-ratified" or d8_authority.get("authority") != "#3960":
        fail("D8 authority is not owner-ratified #3960")
    d8_rows = validate_dense_table(
        D8_TABLE,
        8,
        d8_authority["residents"],
        require_human=True,
    )
    all_rows.extend(d8_rows)
    total += 256

    d9_authority = json.loads(D9_AUTHORITY.read_text(encoding="utf-8"))
    if d9_authority.get("status") != "owner-ratified" or d9_authority.get("authority") != "#4008":
        fail("D9 authority is not owner-ratified #4008")
    d9_rows = validate_dense_table(
        D9_TABLE,
        9,
        d9_authority["residents"],
        require_human=True,
    )
    all_rows.extend(d9_rows)
    total += 512

    validate_compact_uk(all_rows)

    for attr in ("uk", "ukr", "san"):
        seen = {}
        for row in all_rows:
            if row.domain == "D7":
                continue  # Shared glyphs and missing glyphs do not collide across domains.
            value = getattr(row, attr)
            previous = seen.get(value)
            key = (row.domain, row.bits, row.en)
            if previous is not None and previous != key:
                fail(
                    f"{attr}: duplicate surface {value!r} for "
                    f"{previous} and {key}"
                )
            seen[value] = key

    if total != 1020:
        fail(f"expected D1-D9 current residents total 1020 rows, found {total}")

    print("DOMAIN-TABLES: PASS")
    print("files=9 layout=one-domain-per-file")
    print("rows=d1:2,d2:4,d3:8,d4:16,d5:32,d6:64,d7:126,d8:256,d9:512 total=1020")
    print("d7-reserved=0100001,0101010")
    print("D7 symbol availability is independent of semantic residency")
    print("non-D7-surface-collisions=0 namespaces=uk,ukr,san")
    print("uk-style=compact ukr-style=expanded selectors=п/р mutation=! in uk,ukr,en predicate=? in uk,ukr,en")
    print("d9-runtime=W9-carrier-separate-fail-closed-#4038")
    print("columns=ук->укр->san->en->LISP->sym")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""D7 owner-ratified projection — never a host-created semantic identity.

Sound/Text residency comes exclusively from knowledge/d7-ratified.json (#3572),
with human surfaces read from lib/domains/d7.lisp. LocalOrdinal is a distinct
explicitly selected W7 role; it never borrows Sound/Text residency or Number
semantics. This script is a read-only projection, not a runtime Lisp callable.
"""
from __future__ import annotations

import argparse
import json
import re
from pathlib import Path

from domain_tables import D7_TABLE, read_domain_table

ROOT = Path(__file__).resolve().parents[1]
AUTHORITY = ROOT / "knowledge/d7-ratified.json"
NAMESPACES = ("ук", "укр", "san", "en", "sym")
EXACT_W7 = re.compile(r"[01]{7}\Z")


class D7ProjectionError(ValueError):
    """Wrong width, absent residency or ambiguous role; no best-effort alias."""


def load_current_d7() -> tuple[dict, dict[str, object]]:
    owner = json.loads(AUTHORITY.read_text(encoding="utf-8"))
    if (owner["status"], owner["authority"], owner["width"],
        owner["capacity"], owner["occupancy"]) != ("owner-ratified", "#3572", 7, 128, 126):
        raise D7ProjectionError("D7 authority changed; explicit review required")
    pins = set(owner["reserved_coordinates"])
    rows = read_domain_table(D7_TABLE)
    by_coordinate = {row.bits: row for row in rows}
    if (len(by_coordinate) != 126 or set(by_coordinate) != set(owner["residents"])
        or pins != {"0100001", "0101010"}
        or pins.intersection(by_coordinate)):
        raise D7ProjectionError("D7 Lisp table and owner-ratified residency diverged")
    for bits, row in by_coordinate.items():
        if row.en != owner["residents"][bits] or row.lisp is not None:
            raise D7ProjectionError(f"D7:{bits} changed or minted a Lisp callable")
        if row.surface_symbols is None or tuple(row.surface_symbols) != ("ук", "укр", "san", "en", "LISP", "sym"):
            raise D7ProjectionError(f"D7:{bits} is missing the surface-indexed symbol map")
        if row.surface_symbols["LISP"] is not None:
            raise D7ProjectionError(f"D7:{bits} must not invent a Lisp symbol/callable")
    evidence = {item["coordinate"]: item for item in owner["rows"]}
    if len(evidence) != 128:
        raise D7ProjectionError("D7 owner evidence must cover all 128 coordinates")
    for bits in by_coordinate:
        if evidence[bits]["status"] != "OWNER-RATIFIED":
            raise D7ProjectionError(f"D7:{bits} lacks owner admission")
    for bits in pins:
        if evidence[bits]["status"] != "OWNER-RESERVED-PINNED":
            raise D7ProjectionError(f"D7:{bits} lost owner reservation")
    return evidence, by_coordinate


def project(bits: str, *, role: str, namespace: str = "ук") -> dict:
    """Project one explicitly role-qualified W7 word; no inferred meaning."""
    if not EXACT_W7.fullmatch(bits):
        raise D7ProjectionError("D7 requires exactly seven binary digits")
    if namespace not in NAMESPACES:
        raise D7ProjectionError(f"unsupported D7 human namespace: {namespace}")
    if role not in ("sound-text", "local-ordinal"):
        raise D7ProjectionError("D7 role must be explicit: sound-text or local-ordinal")

    evidence, table = load_current_d7()
    if role == "local-ordinal":
        # LocalOrdinal uses ONLY the 14 donor-locked Shiva-sutra ordinals.
        # Equal W7 bits do not mint Sound/Text residency or arithmetic Number.
        corpus = json.loads((ROOT / "benchmarks/d7-local-ordinal-corpus/fixtures/projection.json").read_text(encoding="utf-8"))
        ordinals = {row["bits"]: row for row in corpus["rows"]}
        if len(ordinals) != 14 or set(ordinals) != {f"{i:07b}" for i in range(1, 15)}:
            raise D7ProjectionError("D7 LocalOrdinal donor-locked corpus drift")
        if bits not in ordinals:
            raise D7ProjectionError(f"D7:{bits} has no donor-ratified LocalOrdinal provenance")
        ordinal = ordinals[bits]
        return {
            "domain": "D7", "coordinate": bits, "width": 7,
            "role": "local-ordinal", "status": "D7-VALID-PROVENANCE",
            "donor_ref": ordinal["donor_ref"], "source_order": ordinal["source_order"],
            "surface": None, "callable": False, "arithmetic_number": False,
        }

    row = table.get(bits)
    if row is None:
        raise D7ProjectionError(f"D7:{bits} is reserved; owner admission required")
    owner = evidence[bits]
    # Lisp columns use ук/укр; the structural table reader exposes uk/ukr.
    # Namespaces are presentation only, never the coordinate authority.
    field = {"ук": "uk", "укр": "ukr"}.get(namespace, namespace)
    surface = getattr(row, field)
    # A missing symbol is a valid explicit empty projection; descriptive
    # namespaces still fail closed if their human label itself is absent.
    if surface is None and namespace != "sym":
        raise D7ProjectionError(f"D7:{bits} has no {namespace} projection")
    symbols = row.surface_symbols
    if symbols is None:
        raise D7ProjectionError(f"D7:{bits} lacks a surface-indexed symbol map")
    symbol = symbols.get(namespace)
    return {
        "domain": "D7", "coordinate": bits, "width": 7,
        "role": "sound-text", "semantic_role": owner["semantic_role"],
        "status": "OWNER-RATIFIED", "namespace": namespace,
        # Keep the explanatory label for compatibility and expose the selected
        # surface's actual glyph separately; these are projections, not identity.
        "surface": surface, "symbol": symbol,
        "callable": False, "arithmetic_number": False,
    }


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--check", action="store_true", help="validate owner map and D7 surface projection")
    ap.add_argument("--coordinate", help="exact seven-bit D7 word")
    ap.add_argument("--role", choices=["sound-text", "local-ordinal"])
    ap.add_argument("--namespace", choices=NAMESPACES, default="ук")
    opts = ap.parse_args()
    try:
        if opts.check:
            load_current_d7()
            for bits in ("0000001", "0001110"):
                project(bits, role="local-ordinal")
            for bits in ("0000000", "0001111", "0100001", "0101010"):
                try:
                    project(bits, role="local-ordinal")
                except D7ProjectionError:
                    pass
                else:
                    raise D7ProjectionError(f"unowned LocalOrdinal admitted: {bits}")
            for pin in ("0100001", "0101010"):
                try:
                    project(pin, role="sound-text")
                except D7ProjectionError:
                    pass
                else:
                    raise D7ProjectionError(f"reserved Sound/Text pin admitted: {pin}")
            print("D7-PROJECTION=PASS; owner-residents=126/128; reserved=2; local-ordinals=14; no-Rust-law")
            return 0
        if opts.coordinate is None or opts.role is None:
            ap.error("--coordinate and --role are both required without --check")
        result = project(opts.coordinate, role=opts.role, namespace=opts.namespace)
    except D7ProjectionError as exc:
        ap.exit(2, f"BLOCKED: {exc}\n")
    print(json.dumps(result, ensure_ascii=False, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
